describe('Notification Filter by Type', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.wait(1000);
  });

  it('should filter notifications by info type', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-info"]').click();

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').each(($notification) => {
        cy.wrap($notification).should('have.attr', 'data-notification-type', 'info');
      });
    });

    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
  });

  it('should filter notifications by warning type', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-warning"]').click();

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').each(($notification) => {
        cy.wrap($notification).should('have.attr', 'data-notification-type', 'warning');
      });
    });

    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
  });

  it('should filter notifications by error type', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-error"]').click();

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').each(($notification) => {
        cy.wrap($notification).should('have.attr', 'data-notification-type', 'error');
      });
    });

    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
  });

  it('should display all notifications when filter is cleared', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-info"]').click();
    cy.wait(500);

    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-clear"]').click();

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 1);
    });
  });

  it('should handle multiple filter selections', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-info"]').click();
    cy.get('[data-testid="filter-option-warning"]').click();
    cy.wait(500);

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').each(($notification) => {
        cy.wrap($notification).should('satisfy', ($el) => {
          const type = $el.attr('data-notification-type');
          return type === 'info' || type === 'warning';
        });
      });
    });
  });

  it('should show empty state when no notifications match filter', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-error"]').click();

    cy.get('[data-testid="notification-list"]').within(() => {
      cy.get('[data-testid="notification-item"]').then(($items) => {
        if ($items.length === 0) {
          cy.get('[data-testid="empty-state-message"]').should('be.visible');
          cy.get('[data-testid="empty-state-message"]').should('contain', 'No notifications found');
        }
      });
    });
  });

  it('should persist filter selection when navigating away and back', () => {
    cy.get('[data-testid="notification-filter-dropdown"]').click();
    cy.get('[data-testid="filter-option-warning"]').click();
    cy.wait(500);

    cy.get('[data-testid="notification-item"]').first().should('have.attr', 'data-notification-type', 'warning');

    cy.visit('/dashboard');
    cy.wait(500);
    cy.visit('/notifications');
    cy.wait(500);

    cy.get('[data-testid="notification-filter-dropdown"]').should('have.attr', 'data-selected-filter', 'warning');
    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.attr', 'data-notification-type', 'warning');
    });
  });

  it('should update notification count when filter is applied', () => {
    cy.get('[data-testid="notification-count"]').then(($count) => {
      const initialCount = parseInt($count.text());

      cy.get('[data-testid="notification-filter-dropdown"]').click();
      cy.get('[data-testid="filter-option-info"]').click();
      cy.wait(500);

      cy.get('[data-testid="notification-count"]').then(($filteredCount) => {
        const filteredCountValue = parseInt($filteredCount.text());
        cy.wrap(filteredCountValue).should('be.lte', initialCount);
      });
    });
  });
});
